import{_ as s,C as r,o,c as i,j as a,a as n,E as d,a5 as l}from"./chunks/framework.-jms6n7v.js";const k=JSON.parse(`{"title":"Comparison","description":"How DaruDB's features compare with those of the embedded databases applications use most, feature by feature, for the four languages DaruDB ships for.","frontmatter":{"title":"Comparison","order":2,"aside":false,"pageClass":"compare-page","prev":{"text":"Types","link":"/types/"},"next":{"text":"Performance","link":"/performance"}},"headers":[{"level":2,"title":"What each column describes","slug":"what-each-column-describes","link":"#what-each-column-describes","children":[]},{"level":2,"title":"Speed","slug":"speed","link":"#speed","children":[]},{"level":2,"title":"Sources","slug":"sources","link":"#sources","children":[]}],"relativePath":"compare.md","filePath":"en/compare.md","lastUpdated":1791610329000}`),c={name:"compare.md"};function h(p,e,u,m,g,b){const t=r("CompareTable");return o(),i("div",null,[e[0]||(e[0]=a("h1",{id:"comparing-embedded-databases",tabindex:"-1"},[n("Comparing embedded databases "),a("a",{class:"header-anchor",href:"#comparing-embedded-databases","aria-label":'Permalink to "Comparing embedded databases"'},"​")],-1)),e[1]||(e[1]=a("p",null,"How DaruDB's features compare with those of the embedded databases applications use most, feature by feature, for the four languages DaruDB ships for.",-1)),e[2]||(e[2]=a("p",null,"Each cell marks a feature as supported, partly supported or not supported, and a note says what the mark alone would leave out. A database without a package for the language chosen in the sidebar is faded, and the checkbox above the table hides it.",-1)),d(t),e[3]||(e[3]=l('<h2 id="what-each-column-describes" tabindex="-1">What each column describes <a class="header-anchor" href="#what-each-column-describes" aria-label="Permalink to &quot;What each column describes&quot;">​</a></h2><p>Each column is the database as an application installs it today:</p><ul><li><strong>SQLite</strong> is the library itself and the bindings each language uses most. Encryption comes from extensions, which the cells name.</li><li><strong>Realm</strong> is the open-source SDKs and Realm Core. Their vendor deprecated them in September 2024 and ended support at the end of September 2025.</li><li><strong>ObjectBox</strong> is its current release, whose native core is closed source and free to use.</li><li><strong>Isar</strong> is version 3, the last stable one, as the original package and its community fork <code>isar_community</code> publish it.</li><li><strong>Hive</strong> is version 2, as the original package and its community edition <code>hive_ce</code> publish it.</li><li><strong>LMDB</strong> is the C library, versions 0.9 and 1.0, with the bindings others maintain.</li><li><strong>RocksDB</strong> and <strong>redb</strong> are their current releases, with the bindings others maintain.</li></ul><h2 id="speed" tabindex="-1">Speed <a class="header-anchor" href="#speed" aria-label="Permalink to &quot;Speed&quot;">​</a></h2><p>This page compares features only. <a href="./performance">Performance</a> compares speed: the same workloads, run the same way in every database at the same durability settings, for each language.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><p>Every cell was checked in October 2026 against the project&#39;s own documentation, its source and its package registry pages. Features change from one release to the next, so where a cell and a project&#39;s documentation disagree, the documentation is right, and an <a href="https://github.com/jooy2/darudb/issues" target="_blank" rel="noreferrer">issue</a> saying so is welcome.</p><p>To move an application&#39;s data into DaruDB from one of these databases, see the <a href="./migration/">migration guides</a>.</p>',8))])}const w=s(c,[["render",h]]);export{k as __pageData,w as default};
